import java.util.*;

class Solution {
    public int countSubstrings(String s) {
        int n = s.length(), count = 0;
        for (int centre = 0; centre < 2 * n - 1; centre++) {
            int l = centre / 2, r = l + centre % 2;   // odd centres on letters, even ones on gaps
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                count++;                              // s[l..r] is one more mirror piece
                l--; r++;
            }
        }
        return count;
    }
}

