class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s); res = 0
        for c in range(2 * n - 1):
            l, r = c // 2, c // 2 + c % 2
            while l >= 0 and r < n and s[l] == s[r]:
                res += 1; l -= 1; r += 1
        return res

